scorer.self_check:
in := []string{"c", "a", "b"}
inCopy := append([]string(nil), in...)
out := sortStrings(in)
if !reflect.DeepEqual(out, []string{"a", "b", "c"}) { panic("sort=" + fmt.Sprint(out)) }
if !reflect.DeepEqual(in, inCopy) { panic("mutated input: " + fmt.Sprint(in)) }
if !reflect.DeepEqual(sortStrings(out), out) { panic("not idempotent") }
